template <class T>
struct tree_node
{
  int color;
  tree_node* parent;
  tree_node* left;
  tree_node* right;
  T value;
};

template <class T>
class local_set
{
public:
  typedef tree_node<T> node;

  class iterator
  {
  public:
    node* current;

    iterator(node* p = 0) : current(p) {}

    T operator*() const
    {
      return current->value;
    }

    iterator& operator++()
    {
      if (current->right)
      {
        current = current->right;
        while (current->left)
          current = current->left;
      }
      else
      {
        node* parent = current->parent;
        while (current == parent->right)
        {
          current = parent;
          parent = parent->parent;
        }
        if (current->right != parent)
          current = parent;
      }
      return *this;
    }

    bool operator!=(const iterator& other) const
    {
      return current != other.current;
    }
  };

  node* header;
  unsigned int node_count;
  unsigned int unused;

  iterator begin()
  {
    return iterator(header->left);
  }

  iterator end()
  {
    return iterator(header);
  }

  ~local_set()
  {
    if (node_count)
      erase_tree(header->parent);
    arch_free(header);
  }

private:
  static void erase_tree(node*);
};

template <class T>
class instance_bank
{
public:
  struct ref_t
  {
    stringx label;
    T* ptr;
    unsigned int count;
  };

  typedef local_set<ref_t*> lref_set;
  typedef local_set<ref_t*> pref_set;

  lref_set refs_by_label;
  pref_set refs_by_ptr;

  ~instance_bank();
};

template <class T>
instance_bank<T>::~instance_bank()
{
  lref_set::iterator i;
  for ( i=refs_by_label.begin(); i!=refs_by_label.end(); ++i )
  {
    ref_t* r = *i;
    assert( r->count );
    debug_print( "WARNING: Unreleased instance." );
    delete r;
  }
}

